#ifndef __FORM_H
#define __FORM_H

#include <dolfin/common/Array.h>
#include "DofMapSet.h"
#include <dolfin/function/Function.h>
#include <dolfin/mesh/MeshFunction.h>

#include <ufc.h>

#include <string>

namespace dolfin
{

class SubSystem;

/// Base class for UFC code generated by FFC for DOLFIN with option -l

class Form : public ufc::form
{
public:

  /// Constructor
  Form();

  /// Destructor
  ~Form();

  /// Return array of coefficients
  virtual Array<Function*> const& coefficients() const = 0;

  /// Return number of argument associated with the given name
  uint coefficient_number(const std::string& name) const;

  /// Return name of argument associated with the given number
  std::string coefficient_name(dolfin::uint i) const;

  /// Create degree of freedom maps
  void update_dofmaps(Mesh& mesh) const;

  /// Return DofMapSet
  DofMapSet& dofmaps() const;

  //--- UFC INTERFACE ---------------------------------------------------------
  /// Return a string identifying the form
  const char* signature() const;

  /// Return the rank of the global tensor (r)
  uint rank() const;

  /// Return the number of coefficients (n)
  uint num_coefficients() const;

  /// Return the number of cell integrals
  uint num_cell_integrals() const;

  /// Return the number of exterior facet integrals
  uint num_exterior_facet_integrals() const;

  /// Return the number of interior facet integrals
  uint num_interior_facet_integrals() const;

  /// Create a new finite element for argument function i
  ufc::finite_element* create_finite_element(uint i) const;

  /// Create a new dof map for argument function i
  ufc::dof_map * create_dof_map(uint i) const;

  /// Create a new cell integral on sub domain i
  ufc::cell_integral* create_cell_integral(uint i) const;

  /// Create a new exterior facet integral on sub domain i
  ufc::exterior_facet_integral*
  create_exterior_facet_integral(uint i) const;

  /// Create a new interior facet integral on sub domain i
  ufc::interior_facet_integral* create_interior_facet_integral(uint i) const;

  //--- EXTENSION OF INTERFACE ------------------------------------------------

protected:

  /// Return UFC form
  virtual ufc::form const& form() const = 0;

private:

  // Degree of freedom maps
  mutable DofMapSet * dof_map_set_;

};

//--- INLINES -----------------------------------------------------------------

//-----------------------------------------------------------------------------
inline const char* Form::signature() const
{
  return form().signature();
}

//-----------------------------------------------------------------------------
inline uint Form::rank() const
{
  return form().rank();
}

//-----------------------------------------------------------------------------
inline uint Form::num_coefficients() const
{
  return form().num_coefficients();
}

//-----------------------------------------------------------------------------
inline uint Form::num_cell_integrals() const
{
  return form().num_cell_integrals();
}

//-----------------------------------------------------------------------------
inline uint Form::num_exterior_facet_integrals() const
{
  return form().num_exterior_facet_integrals();
}

//-----------------------------------------------------------------------------
inline uint Form::num_interior_facet_integrals() const
{
  return form().num_interior_facet_integrals();
}

//-----------------------------------------------------------------------------
inline ufc::finite_element* Form::create_finite_element(uint i) const
{
  return form().create_finite_element(i);
}

//-----------------------------------------------------------------------------
inline ufc::dof_map * Form::create_dof_map(uint i) const
{
  return form().create_dof_map(i);
}

//-----------------------------------------------------------------------------
inline ufc::cell_integral* Form::create_cell_integral(uint i) const
{
  return form().create_cell_integral(i);
}

//-----------------------------------------------------------------------------
inline ufc::exterior_facet_integral*
Form::create_exterior_facet_integral(uint i) const
{
  return form().create_exterior_facet_integral(i);
}

//-----------------------------------------------------------------------------
inline ufc::interior_facet_integral*
Form::create_interior_facet_integral(uint i) const
{
  return form().create_interior_facet_integral(i);
}

}

#endif
